import numpy as np
import time
from scipy.signal import fftconvolve


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = fftconvolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    L2 = L * L
    num = np.sum(L2[:-1] + L[:-1] * L[1:] + L2[1:]) / 3.0
    m = L.max()
    if m <= 0:
        return -1.0
    return num / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 0.6

    def oot():
        return time.process_time() - t0 > deadline

    rng = np.random.default_rng(7)

    # Build initial candidate.
    if start is not None:
        h = np.asarray(start, dtype=float).ravel()
        h = np.maximum(h, 0.0)
        if h.size == 0 or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = h / h.max()

    best = h.copy()
    bestR = _R(best)

    def consider(c):
        nonlocal best, bestR
        c = np.maximum(np.asarray(c, dtype=float), 0.0)
        mx = c.max()
        if mx <= 0 or c.sum() <= 0:
            return
        c = c / mx
        r = _R(c)
        if r > bestR:
            bestR = r
            best = c.copy()

    # Family of smooth bumps: cos^a, gaussians, (1-|x|^p)^q, at multiple N.
    for Nc in [40, 64, 100, 150, 200, 300, 500]:
        if oot():
            break
        x = np.linspace(-1, 1, Nc)
