        stall = 0
        while not oot():
            improved = False
            order = rng.permutation(N)
            for i in order:
                if oot():
                    break
                for d in (step, -step):
                    v = cur[i] + d
                    if v < 0:
                        continue
                    old = cur[i]
                    cur[i] = v
                    r = _R(cur)
                    if r > curR:
                        curR = r
                        improved = True
                        break
                    else:
                        cur[i] = old
            if improved:
                stall = 0
                # keep only best
                if curR > bestR:
                    bestR = curR
                    best = cur.copy()
            else:
                step *= 0.6
                stall += 1
                if step < 1e-4:
