import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    s = h.sum()
    if not np.isfinite(s) or s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    mx = L.max()
    if mx <= 0:
        return -1.0
    return num / (s * s * mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    def oot():
        return time.process_time() > deadline

    rng = np.random.default_rng(987654321)

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.max(s) > 0:
            v = _R(s)
            if v > best_R:
                best_R = v
                best = s.copy()
    if best is None:
        best = np.ones(50)
        best_R = _R(best)

    # Normalize best to max=1
    def norm(c):
        c = np.maximum(np.asarray(c, dtype=float), 0.0)
        m = c.max()
        if m <= 0:
            return None
        return c / m

    # Try a parametric family: flat top with power-law ramps
    # shape: ramps of length w with exponent p, flat middle of length M
    def make_shape(M, w, p):
        N = M + 2 * w
        h = np.ones(N)
        for i in range(w):
            x = (i + 1) / (w + 1.0)
            v = x ** p
            h[i] = v
            h[N - 1 - i] = v
        return h

    def try_c(c):
        nonlocal best, best_R
        c = norm(c)
        if c is None:
            return
        r = _R(c)
        if r > best_R:
            best_R = r
            best = c

    # Broad parametric scan
    for M in (10, 20, 40, 60, 100, 200, 400, 800):
        for w in (1, 2, 3, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96):
            for p in (0.4, 0.6, 0.8, 1.0, 1.3, 1.6, 2.0, 2.5, 3.0, 4.0):
                if oot():
                    break
                try_c(make_shape(M, w, p))
            if oot():
                break
        if oot():
            break

    # Also try pure power-law and Gaussian-ish shapes
    for Nc in (30, 50, 80, 120, 200, 300, 500):
        for p in (0.5, 1.0, 1.5, 2.0, 3.0):
            if oot():
                break
            xx = np.linspace(-1, 1, Nc)
            try_c(np.maximum(1 - np.abs(xx), 0) ** p)
        for sig in (0.15, 0.2, 0.25, 0.3, 0.4):
            if oot():
                break
            xx = np.linspace(-1, 1, Nc)
            try_c(np.exp(-0.5 * (xx / sig) ** 2))

    if oot():
        return best

    # Local coordinate ascent with adaptive step, more aggressive schedule
    # Use the current best's shape; perturb few coordinates each iteration.
    N = best.size
    cur = best.copy()
    cur_R = best_R
    step = 0.15
    stall = 0
    max_stall = 400

    while not oot():
        # pick random small subset of coordinates to perturb
        k = max(1, min(N, 4))
        idx = rng.integers(0, N, size=k)
        cand = cur.copy()
        for i in idx:
            cand[i] = max(0.0, cand[i] + rng.normal(0, step))
        c = norm(cand)
        if c is None:
            continue
        r = _R(c)
        if r > cur_R:
            cur_R = r
            cur = c
            if r > best_R:
                best_R = r
                best = c.copy()
            stall = 0
        else:
            stall += 1
            if stall > max_stall:
                step *= 0.7
                stall = 0
                if step < 1e-5:
                    # resample length: try changing N
                    newN = int(np.clip(N + rng.integers(-10, 11), 5, 50000))
                    xp = np.linspace(0, 1, N)
                    xq = np.linspace(0, 1, newN)
                    cur = norm(np.interp(xq, xp, cur))
                    if cur is None:
                        cur = best.copy()
                        newN = N
                    N = newN
                    cur_R = _R(cur)
                    step = 0.1

    return best

