    best = None
    best_R = -1.0

    def norm(c):
        c = np.clip(np.asarray(c, dtype=float).ravel(), 0.0, None)
        if c.size == 0 or c.sum() <= 0:
            return None
        m = c.max()
        if m <= 0:
            return None
        return c / m

    def consider(c):
        nonlocal best, best_R
        c = norm(c)
        if c is None:
            return -1.0
        r = _R(c)
        if r > best_R:
            best_R = r
            best = c.copy()
        return r

    if start is not None:
        consider(start)

    # Parametric seeds
    def make_shape(M, w, p):
        N = M + 2 * w
        h = np.ones(N)
        for i in range(w):
            x = (i + 1) / (w + 1.0)
            v = x ** p
            h[i] = v
            h[N - 1 - i] = v
        return h

    if best is None:
        for M in (5, 10, 20, 40, 80, 160, 320):
            for w in (2, 4, 8, 16, 32, 64):
                for p in (0.5, 1.0, 1.5, 2.0, 3.0):
                    consider(make_shape(M, w, p))
    if best is None:
        best = np.ones(50)
        best_R = _R(best)

    # Resample helper
    def resample(src, N):
        xs = np.linspace(0, 1, src.size)
        xn = np.linspace(0, 1, N)
        return np.interp(xn, xs, src)

    # Coordinate ascent with multiple step sizes per coordinate
    def refine(c, end_time, step0):
        nonlocal best, best_R
        c = norm(c)
        if c is None:
            return None
        r = _R(c)
        Nc = c.size
        step = step0
        while time.process_time() < end_time:
            improved = False
            order = rng.permutation(Nc)
            for i in order:
                if time.process_time() >= end_time:
                    break
                old = c[i]
                best_d = 0.0
                best_r = r
                for d in (step, -step, 0.5 * step, -0.5 * step, 2.0 * step, -2.0 * step):
                    v = old + d
                    if v < 0:
                        continue
                    c[i] = v
                    rr = _R(c)
                    if rr > best_r + 1e-13:
                        best_r = rr
                        best_d = d
                if best_d != 0.0:
                    c[i] = old + best_d
                    r = best_r
                    improved = True
                else:
                    c[i] = old
            if r > best_R:
                best_R = r
                best = c.copy()
            if not improved:
                step *= 0.55
                if step < 1e-8:
                    break
        return c

    # Stage 1: refine current best
    refine(best, t0 + (deadline - t0) * 0.30, 0.25)

    # Stage 2: try alternate resolutions
    sizes = [140, 180, 200, 220, 260, 300, 360, 420]
    rng.shuffle(sizes)
    for Nalt in sizes:
        if oot() or time.process_time() >= t0 + (deadline - t0) * 0.80:
            break
        c = resample(best, Nalt)
        consider(c)
        end = min(deadline, time.process_time() + 1.5)
        refine(c, end, 0.2)

    # Stage 3: perturb-and-polish
    while not oot():
        frac = (time.process_time() - t0) / (deadline - t0)
        sigma = 0.02 + 0.03 * (1.0 - frac)
        c = best + rng.normal(0.0, sigma, size=best.size)
        c = norm(c)
        if c is None:
            continue
        if _R(c) > best_R - 5e-4:
            end = min(deadline, time.process_time() + 0.8)
            refine(c, end, 0.08)

    # Final polish at best resolution
    refine(best, deadline, 0.05)

    print("final R ~", best_R, "N =", best.size)
    return best

