        state["best"] = np.ones(120)
        state["best_R"] = _R(state["best"])

    def resample(src, N):
        xs = np.linspace(0, 1, src.size)
        xn = np.linspace(0, 1, N)
        return np.interp(xn, xs, src)

    # Analytic gradient of R w.r.t. h, given L = conv(h,h).
    def grad_R(h, L=None):
        s = h.sum()
        if s <= 0:
            return None, -1.0
        if L is None:
            L = np.convolve(h, h)
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0:
            return None, -1.0
        denom = 3.0 * s * s * m
        R = num / denom
        dnum = np.zeros_like(L)
        dnum[:-1] += (2.0 * a + b) / 3.0
        dnum[1:] += (a + 2.0 * b) / 3.0
        imax = int(np.argmax(L))
        dR_dL = dnum / denom
        dR_dL[imax] -= num / (3.0 * s * s * m * m)
        dR_ds = -2.0 * num / (3.0 * s * s * s * m)
        g = 2.0 * np.correlate(dR_dL, h, mode='full')[h.size - 1:h.size - 1 + h.size]
        g = g + dR_ds
        return g, R

    def grad_ascent(c, end_time, lr0=0.05, max_iters=2000):
        c = norm(c)
        if c is None:
            return None
        L = np.convolve(c, c)
        r = R_from_L(L, c.sum())
        lr = lr0
        for _ in range(max_iters):
            if time.process_time() >= end_time or oot():
                break
            g, r = grad_R(c, L)
            if g is None:
                break
            gn = np.linalg.norm(g)
            if gn < 1e-16:
                break
            improved = False
            for mult in (1.0, 0.5, 0.25, 2.0, 0.1, 0.05, 4.0):
                trial = norm(np.clip(c + (lr * mult / gn) * g, 0.0, None))
                if trial is None:
                    continue
                Lt = np.convolve(trial, trial)
                rt = R_from_L(Lt, trial.sum())
                if rt > r + 1e-16:
                    c = trial; L = Lt; r = rt
                    lr *= 1.2 * mult
                    improved = True
                    if r > state["best_R"]:
                        state["best_R"] = r
                        state["best"] = c.copy()
                    break
            if not improved:
                lr *= 0.5
                if lr < 1e-13:
                    break
        return c

    # Coordinate descent using exact rank-1 update of L.
    def refine(c, end_time, step0, use_pairs=True):
        c = norm(c)
        if c is None:
            return None
        r, L = _R(c), np.convolve(c, c)
        Nc = c.size
        step = step0
        while time.process_time() < end_time and not oot():
            improved = False
            order = rng.permutation(Nc)
            for i in order:
                if time.process_time() >= end_time or oot():
                    break
                old = c[i]
                best_d = 0.0
                best_r = r
                ks = np.arange(i, i + Nc)
                base = L[ks]
                for d in (step, -step, 0.5 * step, -0.5 * step,
                          2.0 * step, -2.0 * step, 0.25 * step, -0.25 * step):
                    v = old + d
                    if v < 0:
                        continue
                    L2 = L.copy()
                    L2[ks] = base + 2.0 * d * c
                    L2[2 * i] += d * d
                    rr = R_from_L(L2, c.sum() + d)
                    if rr > best_r + 1e-16:
                        best_r = rr; best_d = d
                if best_d != 0.0:
                    c[i] = old + best_d
                    L = np.convolve(c, c)
                    r = best_r
                    improved = True
            if use_pairs and not oot() and time.process_time() < end_time:
                for _ in range(max(1, Nc // 2)):
                    if time.process_time() >= end_time or oot():
                        break
                    i, j = rng.integers(0, Nc, 2)
                    if i == j:
                        continue
                    oi, oj = c[i], c[j]
                    best_r = r
