def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def oot():
        return time.process_time() > deadline

    rng = np.random.default_rng(20240611)
    state = {"best": None, "best_R": -1.0}

    def norm(c):
        c = np.clip(np.asarray(c, dtype=float).ravel(), 0.0, None)
        if c.size == 0:
            return None
        m = c.max()
        if m <= 0 or c.sum() <= 0:
            return None
        return c / m

    def R_from_L(L, s):
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0 or s <= 0:
            return -1.0
        return (num / 3.0) / (s * s * m)

    def _R(h):
        s = h.sum()
        if s <= 0:
            return -1.0
        return R_from_L(np.convolve(h, h), s)

    def consider(c):
        c = norm(c)
        if c is None:
            return -1.0
        r = _R(c)
        if r > state["best_R"]:
            state["best_R"] = r
            state["best"] = c.copy()
        return r

