        g = 2.0 * np.correlate(dR_dL, h, mode='full')[h.size - 1:h.size - 1 + h.size]
        g = g + dR_ds
        return g, R

    # NEW: L-BFGS on smooth negative-R (argmax knot pinned). Much faster per
    # iteration than coordinate descent for moderate N.
    def lbfgs_polish(c, end_time, maxiter=400):
        c = norm(c)
        if c is None:
            return None
        c = c.copy()

        def negR(x):
            if oot() or time.process_time() >= end_time:
                raise StopIteration
            h = np.clip(x, 0.0, None)
            L = np.convolve(h, h)
            s = h.sum()
            if s <= 0:
                return 1e9
            return -R_from_L(L, s)

