                           bounds=[(0.0, None)] * c.size,
                           options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            cand = norm(res.x)
            if cand is not None:
                consider(cand)
                return cand
        except StopIteration:
            pass
        except Exception:
