    deadline = t0 + budget_seconds - 1.2

    def oot():
        return time.process_time() > deadline

    rng = np.random.default_rng(20240917)

    def norm(c):
        c = np.clip(np.asarray(c, dtype=float).ravel(), 0.0, None)
        if c.size == 0:
            return None
        m = c.max()
        if m <= 0 or c.sum() <= 0:
            return None
        return c / m

    def R_from_L(L, s):
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0 or s <= 0:
            return -1.0
        return (num / 3.0) / (s * s * m)

    def _R(h):
        s = h.sum()
        if s <= 0:
            return -1.0
        return R_from_L(np.convolve(h, h), s)

    state = {"best": None, "best_R": -1.0}

    def consider(c):
        c = norm(c)
        if c is None:
            return -1.0
        r = _R(c)
        if r > state["best_R"]:
            state["best_R"] = r
            state["best"] = c.copy()
        return r

    if start is not None:
        consider(start)
    if state["best"] is None:
        x = np.linspace(-1, 1, 200)
        consider(np.cos(0.5 * np.pi * x) ** 2)
    if state["best"] is None:
        state["best"] = np.ones(120)
        state["best_R"] = _R(state["best"])

    def resample(src, N):
        xs = np.linspace(0, 1, src.size)
        xn = np.linspace(0, 1, N)
        return np.interp(xn, xs, src)

    def grad_R(h, L=None):
        s = h.sum()
        if s <= 0:
            return None, -1.0
        if L is None:
            L = np.convolve(h, h)
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0:
            return None, -1.0
        denom = 3.0 * s * s * m
        R = num / denom
        dnum = np.zeros_like(L)
        dnum[:-1] += (2.0 * a + b) / 3.0
        dnum[1:] += (a + 2.0 * b) / 3.0
        imax = int(np.argmax(L))
        dR_dL = dnum / denom
        dR_dL[imax] -= num / (3.0 * s * s * m * m)
        dR_ds = -2.0 * num / (3.0 * s * s * s * m)
        g = 2.0 * np.correlate(dR_dL, h, mode='full')[h.size - 1:h.size - 1 + h.size]
        g = g + dR_ds
        return g, R

    def grad_ascent(c, end_time, lr0=0.05, max_iters=4000):
        c = norm(c)
        if c is None:
            return None
        L = np.convolve(c, c)
        r = R_from_L(L, c.sum())
        lr = lr0
        y = c.copy()
        tk = 1.0
        for _ in range(max_iters):
            if time.process_time() >= end_time or oot():
                break
            g, r = grad_R(y, np.convolve(y, y))
            if g is None:
                break
            gn = np.linalg.norm(g)
            if gn < 1e-16:
                break
            improved = False
            for mult in (1.0, 0.5, 0.25, 2.0, 0.1, 0.05, 4.0, 0.02, 0.01):
                trial = norm(np.clip(y + (lr * mult / gn) * g, 0.0, None))
                if trial is None:
                    continue
                Lt = np.convolve(trial, trial)
                rt = R_from_L(Lt, trial.sum())
                if rt > r + 1e-16:
                    tk1 = 0.5 * (1.0 + np.sqrt(1.0 + 4.0 * tk * tk))
                    y = norm(np.clip(trial + ((tk - 1.0) / tk1) * (trial - c), 0.0, None))
                    c = trial; L = Lt; r = rt
                    tk = tk1
                    lr *= 1.2 * mult
                    improved = True
                    if r > state["best_R"]:
                        state["best_R"] = r
                        state["best"] = c.copy()
                    break
            if not improved:
                lr *= 0.5
                y = c.copy(); tk = 1.0
                if lr < 1e-14:
                    break
        return c

    def refine(c, end_time, step0, use_pairs=True):
        c = norm(c)
        if c is None:
            return None
        r, L = _R(c), np.convolve(c, c)
        Nc = c.size
        step = step0
        while time.process_time() < end_time and not oot():
            improved = False
            order = rng.permutation(Nc)
            for i in order:
                if time.process_time() >= end_time or oot():
                    break
                old = c[i]
                best_d = 0.0
                best_r = r
                ks = np.arange(i, i + Nc)
                base = L[ks]
                for d in (step, -step, 0.5 * step, -0.5 * step,
                          2.0 * step, -2.0 * step, 0.25 * step, -0.25 * step):
                    v = old + d
                    if v < 0:
                        continue
                    L2 = L.copy()
                    L2[ks] = base + 2.0 * d * c
                    L2[2 * i] += d * d
                    rr = R_from_L(L2, c.sum() + d)
                    if rr > best_r + 1e-16:
                        best_r = rr; best_d = d
                if best_d != 0.0:
                    c[i] = old + best_d
                    L = np.convolve(c, c)
                    r = best_r
                    improved = True
            if use_pairs and not oot() and time.process_time() < end_time:
                for _ in range(max(1, Nc // 2)):
                    if time.process_time() >= end_time or oot():
                        break
                    i, j = rng.integers(0, Nc, 2)
                    if i == j:
                        continue
                    oi, oj = c[i], c[j]
                    best_r = r
                    best_pair = None
                    for amt in (step, -step, 0.5 * step, -0.5 * step):
                        ni = oi - amt; nj = oj + amt
                        if ni < 0 or nj < 0:
                            continue
                        c[i], c[j] = ni, nj
                        rr = _R(c)
                        if rr > best_r + 1e-15:
                            best_r = rr; best_pair = (ni, nj)
                    if best_pair is not None:
                        c[i], c[j] = best_pair
                        r = best_r
                        L = np.convolve(c, c)
                        improved = True
                    else:
                        c[i], c[j] = oi, oj
            if r > state["best_R"]:
                state["best_R"] = r
                state["best"] = c.copy()
            if not improved:
                step *= 0.55
                if step < 1e-12:
                    break
        return c

    total = deadline - t0

    # Stage 1: strong polish of the start with gradient ascent
    grad_ascent(state["best"], t0 + total * 0.10, lr0=0.04)
    refine(state["best"], t0 + total * 0.20, 0.02, use_pairs=True)

    # Stage 2: multi-resolution exploration -- the key to escaping the
    # fixed-N plateau. Try many nearby sizes, gradient-polish, keep best.
    base_N = state["best"].size
    fracs = (1.0, 1.002, 0.998, 1.005, 0.995, 1.01, 0.99, 1.02, 0.98,
             1.03, 0.97, 1.05, 0.95, 1.07, 0.93, 1.1, 0.9, 1.13, 0.87,
             1.17, 0.83, 1.22, 0.78, 1.3, 0.7, 1.4, 0.6, 1.5, 0.5, 0.45)
    sizes = sorted(set([max(2, int(round(base_N * f))) for f in fracs]))
    sizes = [s for s in sizes if 2 <= s <= 50000]
    for Nalt in sizes:
        if oot() or time.process_time() - t0 > total * 0.55:
            break
        c = resample(state["best"], Nalt)
        consider(c)
        end = min(deadline, time.process_time() + total * 0.03)
        grad_ascent(c, end, lr0=0.04)
        refine(c, end, 0.02, use_pairs=True)

    # Stage 3: perturb-and-polish (basin hopping) with block perturbations
    while not oot():
        frac = (time.process_time() - t0) / max(1e-9, total)
        if frac > 0.93:
            break
        c = state["best"].copy()
        nc = c.size
        if rng.random() < 0.5:
            sigma = 0.002 + 0.02 * (1.0 - frac)
            c = c + rng.normal(0.0, sigma, size=nc)
        else:
            npert = max(1, int(nc * (0.02 + 0.06 * (1.0 - frac))))
            lo = rng.integers(0, max(1, nc - npert))
            c[lo:lo + npert] *= (0.5 + rng.random())
        c = norm(c)
        if c is None:
            continue
        end = min(deadline, time.process_time() + total * 0.02)
        grad_ascent(c, end, lr0=0.03, max_iters=1500)
        refine(c, end, 0.015, use_pairs=True)

    # Final intensification on the best
    if not oot():
        grad_ascent(state["best"], deadline, lr0=0.02, max_iters=2000)

    best = state["best"]
    if best is None:
        best = np.ones(64)
    if best.size > 50000:
        best = best[:50000]
    print("final R ~", state["best_R"], "N =", best.size)
    return np.asarray(best, dtype=float)

