import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    def oot():
        return time.process_time() > deadline

    rng = np.random.default_rng(13579)

    state = {"best": None, "best_R": -1.0}

    def norm(c):
        c = np.clip(np.asarray(c, dtype=float).ravel(), 0.0, None)
        if c.size == 0:
            return None
        m = c.max()
        if m <= 0 or c.sum() <= 0:
            return None
        return c / m

    def R_from_L(L, s):
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0 or s <= 0:
            return -1.0
        return (num / 3.0) / (s * s * m)

    def _R(h):
        s = h.sum()
        if s <= 0:
            return -1.0
        return R_from_L(np.convolve(h, h), s)

    def consider(c):
        c = norm(c)
        if c is None:
            return -1.0
        r = _R(c)
        if r > state["best_R"]:
            state["best_R"] = r
            state["best"] = c.copy()
        return r

    if start is not None:
        consider(start)
    if state["best"] is None:
        x = np.linspace(-1, 1, 300)
        consider(np.exp(-0.5 * (x / 0.4) ** 2))
    if state["best"] is None:
        state["best"] = np.ones(120)
        state["best_R"] = _R(state["best"])

    def resample(src, N):
        xs = np.linspace(0, 1, src.size)
        xn = np.linspace(0, 1, N)
        return np.interp(xn, xs, src)

    def grad_R(h, L=None):
        s = h.sum()
        if s <= 0:
            return None, -1.0
        if L is None:
            L = np.convolve(h, h)
        a = L[:-1]; b = L[1:]
        num = np.dot(a, a) + np.dot(a, b) + np.dot(b, b)
        m = L.max()
        if m <= 0:
            return None, -1.0
        denom = 3.0 * s * s * m
        R = num / denom
        dnum = np.zeros_like(L)
        dnum[:-1] += (2.0 * a + b) / 3.0
        dnum[1:] += (a + 2.0 * b) / 3.0
        imax = int(np.argmax(L))
        dR_dL = dnum / denom
        dR_dL[imax] -= num / (3.0 * s * s * m * m)
        dR_ds = -2.0 * num / (3.0 * s * s * s * m)
        g = 2.0 * np.correlate(dR_dL, h, mode='full')[h.size - 1:h.size - 1 + h.size]
        g = g + dR_ds
        return g, R

    def grad_ascent(c, end_time, lr0=0.05, max_iters=4000):
        c = norm(c)
        if c is None:
            return None
        L = np.convolve(c, c)
        r = R_from_L(L, c.sum())
        lr = lr0
        y = c.copy()
        tk = 1.0
        for _ in range(max_iters):
            if time.process_time() >= end_time or oot():
                break
            g, r = grad_R(y, np.convolve(y, y))
            if g is None:
                break
            gn = np.linalg.norm(g)
            if gn < 1e-16:
                break
            improved = False
            for mult in (1.0, 0.5, 0.25, 2.0, 0.1, 0.05, 4.0, 0.02, 0.01):
                trial = norm(np.clip(y + (lr * mult / gn) * g, 0.0, None))
                if trial is None:
                    continue
                Lt = np.convolve(trial, trial)
                rt = R_from_L(Lt, trial.sum())
                if rt > r + 1e-16:
                    tk1 = 0.5 * (1.0 + np.sqrt(1.0 + 4.0 * tk * tk))
                    y = norm(np.clip(trial + ((tk - 1.0) / tk1) * (trial - c), 0.0, None))
                    c = trial; L = Lt; r = rt
                    tk = tk1
                    lr *= 1.2 * mult
                    improved = True
                    if r > state["best_R"]:
                        state["best_R"] = r
                        state["best"] = c.copy()
                    break
            if not improved:
                lr *= 0.5
                y = c.copy(); tk = 1.0
                if lr < 1e-13:
                    break
        return c

    def refine(c, end_time, step0, use_pairs=True):
        c = norm(c)
        if c is None:
            return None
        r = _R(c)
        Nc = c.size
        step = step0
        while time.process_time() < end_time and not oot():
            improved = False
            order = rng.permutation(Nc)
            for i in order:
                if time.process_time() >= end_time or oot():
                    break
                old = c[i]
                best_d = 0.0
                best_r = r
                for d in (step, -step, 0.5 * step, -0.5 * step,
                          2.0 * step, -2.0 * step, 0.25 * step, -0.25 * step):
                    v = old + d
                    if v < 0:
                        continue
                    c[i] = v
                    rr = _R(c)
                    if rr > best_r + 1e-15:
                        best_r = rr
                        best_d = d
                if best_d != 0.0:
                    c[i] = old + best_d
                    r = best_r
                    improved = True
                else:
                    c[i] = old
            if use_pairs and not oot() and time.process_time() < end_time:
                for _ in range(max(1, Nc // 3)):
                    if time.process_time() >= end_time or oot():
                        break
                    i, j = rng.integers(0, Nc, 2)
                    if i == j:
                        continue
                    # prefer nearby pairs to smooth locally
                    if rng.random() < 0.5:
                        j = (i + rng.integers(1, 4)) % Nc
                    oi, oj = c[i], c[j]
                    best_r = r
                    best_pair = None
                    for amt in (step, -step, 0.5 * step, -0.5 * step):
                        ni = oi - amt
                        nj = oj + amt
                        if ni < 0 or nj < 0:
