            if r > state["best_R"]:
                state["best_R"] = r
                state["best"] = c.copy()
            if not improved:
                step *= 0.55
                if step < 1e-12:
                    break
        return c

    total = deadline - t0

    # Stage 1: polish the start
    grad_ascent(state["best"], t0 + total * 0.08, lr0=0.04)
    refine(state["best"], t0 + total * 0.18, 0.02, use_pairs=True)

    # Stage 2: multi-resolution exploration
